+package com.example;
+
+import com.example.MessageStore.Message;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final MessageStore store;
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+        setSizeFull();
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+        name.setRequired(false);
+        email.setRequired(false);
+        phone.setRequired(false);
+        message.setRequired(false);
+        message.setMaxLength(501);
+        Grid<Message> grid = new Grid<>();
+        grid.addColumn(Message::name).setHeader("Name");
+        grid.addColumn(Message::message).setHeader("Message");
+        grid.setItems(store.newestFirst());
+
+        send.addClickListener(event -> submit());
+        send.setDisableOnClick(false);
+        name.addValueChangeListener(event -> edited());
+        email.addValueChangeListener(event -> edited());
+        phone.addValueChangeListener(event -> edited());
+        message.addValueChangeListener(event -> edited());
+        name.addKeyPressListener(Key.ENTER, event -> submit());
+        email.addKeyPressListener(Key.ENTER, event -> submit());
+        phone.addKeyPressListener(Key.ENTER, event -> submit());
+        message.addKeyPressListener(Key.ENTER, event -> submit());
+        add(name, email, phone, message, send, grid);
+    }
+
+    private void edited() {
+        if (!send.isEnabled()) send.setEnabled(true);
+    }
+
+    private void submit() {
+        String n = name.getValue() == null ? "" : name.getValue().trim();
+        String e = email.getValue() == null ? "" : email.getValue().trim();
+        String p = phone.getValue() == null ? "" : phone.getValue().trim();
+        String m = message.getValue() == null ? "" : message.getValue();
+        name.setInvalid(n.isEmpty());
+        name.setErrorMessage("Name is required");
+        boolean invalidEmail = !e.isEmpty() && !e.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+        email.setInvalid(invalidEmail || (e.isEmpty() && p.isEmpty()));
+        email.setErrorMessage(invalidEmail ? "Enter a valid e-mail address" : "Give an e-mail address or a phone number");
+        message.setInvalid(m.trim().isEmpty() || m.length() > 500);
+        message.setErrorMessage(m.trim().isEmpty() ? "Message is required" : "Message must be at most 500 characters");
+        if (n.isEmpty() || invalidEmail || (e.isEmpty() && p.isEmpty()) || m.trim().isEmpty() || m.length() > 500) return;
+
+        Message sent = new Message(n, e, p, m);
+        store.add(sent);
+        // Update this component's grid from the store's canonical newest-first list.
+        getChildren().filter(Grid.class::isInstance).map(Grid.class::cast).forEach(grid -> grid.setItems(store.newestFirst()));
+        name.clear(); email.clear(); phone.clear(); message.clear();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (isEmpty(name) && isEmpty(email.getValue()) && isEmpty(phone) && isEmpty(message)) return;
+        ContinueNavigationAction action = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.add("You have unsent changes.");
+        Button keep = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.add(keep, discard);
+        dialog.open();
+    }
+
+    private boolean isEmpty(TextField field) {
+        return isEmpty(field.getValue());
+    }
+    private boolean isEmpty(TextArea field) {
+        return isEmpty(field.getValue());
+    }
+    private boolean isEmpty(String value) {
+        return value == null || value.isEmpty();
+    }
+}
